bash -lc python - <<'PY'
import re, subprocess
f='/mnt/data/CG_logs/Rate Limit Discussion(1).pdf'
t=subprocess.check_output(['pdftotext','-layout',f,'-'],text=True)
ms=list(re.finditer(r'(?m)^\s*(You|ChatGPT) said:\s*$',t))
u=[]
for i,m in enumerate(ms):
 if m.group(1)=='You':
  s=re.sub(r'\s+',' ',t[m.end():(ms[i+1].start() if i+1<len(ms) else len(t))]).strip()
  if len(s)>50:u.append(s)
for i,s in enumerate(u,1):
 print(f'{i:3} {s[:230]}')
